CREATE OR REPLACE PROCEDURE recalc_market_impact_cost()
LANGUAGE plpgsql
AS $$
DECLARE
    rec RECORD;
    v_market_factor REAL;
    v_large_order_ratio NUMERIC;
    v_order_quantity NUMERIC;
    v_limit_price NUMERIC;
    v_mic NUMERIC;
BEGIN
    -- Loop through all new orders
    FOR rec IN
        SELECT 
            o."ORD_STAMP",
            o."exchSpot",
            (o."order_attributes"->>'quantity')::NUMERIC as order_quantity,
            (o."order_attributes"->>'limit_price')::NUMERIC as limit_price,
            md."EXCH_SPOT",
            ai.indicator_bundle->'order_flow'->>'large_order_ratio' as large_order_ratio
        FROM orders o
        JOIN marketdata md ON o."exchSpot" = md."EXCH_SPOT"
        LEFT JOIN analyticsindicators ai ON md."EXCH_SPOT" = ai."md_ref"
        WHERE o."order_attributes"->>'status' = 'New'
    LOOP
        -- Get current market factor from marketstats
        SELECT ms."fundRate" INTO v_market_factor
        FROM marketstats ms
        WHERE ms."md_link" = rec."EXCH_SPOT"
        ORDER BY ms."FundSpot" DESC
        LIMIT 1;

        -- Default market factor to 1 if not found
        IF v_market_factor IS NULL THEN
            v_market_factor := 1;
        END IF;

        -- Parse values
        v_order_quantity := COALESCE(rec.order_quantity, 0);
        v_limit_price := COALESCE(rec.limit_price, 0);
        v_large_order_ratio := COALESCE((rec.large_order_ratio)::NUMERIC, 0);

        -- Calculate MIC using formula: order quantity * limit price * large order ratio * 0.01
        v_mic := v_order_quantity * v_limit_price * v_large_order_ratio * 0.01;

        -- Log the result
        INSERT INTO market_impact_cost_log (ordersmark, mic)
        VALUES (rec."ORD_STAMP", v_mic);
    END LOOP;
END;
$$;

