CREATE OR REPLACE PROCEDURE recalc_market_impact_cost()
LANGUAGE plpgsql
AS $$
DECLARE
    v_mic NUMERIC;
    v_ordersmark TEXT;
    v_market_factor REAL;
BEGIN
    FOR v_ordersmark IN SELECT "ORD_STAMP" FROM orders WHERE "order_attributes"->>'status' = 'New'
    LOOP
        SELECT 
            COALESCE((o."order_attributes"->>'quantity')::NUMERIC, 0) * 
            COALESCE((o."order_attributes"->>'limit_price')::NUMERIC, 0) * 
            COALESCE((ai.indicator_bundle->'order_flow'->>'large_order_ratio')::NUMERIC, 0) * 
            0.01 *
            COALESCE(ms."fundRate", 1)
        INTO v_mic
        FROM orders o
        JOIN marketdata md ON o."exchSpot" = md."EXCH_SPOT"
        LEFT JOIN analyticsindicators ai ON md."EXCH_SPOT" = ai."md_ref"
        LEFT JOIN LATERAL (
            SELECT "fundRate" FROM marketstats WHERE "md_link" = md."EXCH_SPOT" ORDER BY "FundSpot" DESC LIMIT 1
        ) ms ON true
        WHERE o."ORD_STAMP" = v_ordersmark;

        INSERT INTO market_impact_cost_log (ordersmark, mic) VALUES (v_ordersmark, v_mic);
    END LOOP;
END;
$$;

